// provenance.js — what an edge says about where it came from, in plain lines
// for its hover label: its why, then the PROV pair rosetta-tagz writes on a
// tag assertion or a relation (rosetta-tagz/docs/FORMATS.md): wasDerivedFrom,
// the evidence, read as "derived from", and wasGeneratedBy, the activity and
// the parameters that admitted it, read as "generated by".
//
// Pure, so it can be tested without the DOM.

// A line of text broken at spaces into lines of at most width characters; a
// word longer than that keeps a line of its own.
function wrapText(text, width = 48) {
  const words = String(text || '').split(/\s+/).filter(Boolean);
  const lines = [];
  let line = '';
  for (const w of words) {
    if (!line) line = w;
    else if (line.length + 1 + w.length <= width) line += ' ' + w;
    else { lines.push(line); line = w; }
  }
  if (line) lines.push(line);
  return lines;
}

const quoted = (s) => `"${s}"`;
const KEEP = '\u0000'; // joins words wrapText must not break apart
const value = (v) => (v !== null && typeof v === 'object' ? JSON.stringify(v) : String(v));

// One piece of evidence (a wasDerivedFrom entry) as a phrase.
function evidencePhrase(e) {
  if (!e || typeof e !== 'object') return e === undefined || e === null ? '' : String(e);
  switch (e.type) {
    case 'category':
      return `the tag ${quoted(e.label)}${e.scheme ? ` written in ${e.scheme}` : ''}`;
    case 'text':
      if (typeof e.phrase === 'string') {
        const times = typeof e.count === 'number' ? `, ${e.count}×` : '';
        return `${quoted(e.phrase)} in the text${times}${e.inTitle ? ', in the title' : ''}`;
      }
      if (typeof e.cosine === 'number') return `texts alike, cosine ${e.cosine}`;
      break;
    case 'cooccurrence':
      return typeof e.items === 'number' ? `${e.items} items carrying both` : 'items carrying both';
    case 'stem':
      return e.key ? `the shared words ${quoted(e.key)}` : 'shared words';
    case 'signal':
      return `the ${e.name} signal${typeof e.score === 'number' ? ` ${e.score}` : ''}`;
    case 'seed':
      return 'a seed list';
    case 'override':
      return e.note ? `an override (${e.note})` : 'an override';
    default:
      break;
  }
  const rest = Object.entries(e).filter(([k]) => k !== 'type').map(([k, v]) => `${k} ${value(v)}`);
  return [e.type, ...rest].filter(Boolean).join(' ');
}

// The PROV pair as lines: "derived from: …" (one entry after another, ';'
// between) and "generated by: <activity>, with <parameter value>, …". A field
// that is absent or empty writes no line.
function provenanceLines(attrs, { width = 48 } = {}) {
  const lines = [];
  if (!attrs || typeof attrs !== 'object') return lines;
  const derived = attrs.wasDerivedFrom;
  const list = Array.isArray(derived) ? derived : (derived && typeof derived === 'object' ? [derived] : []);
  const phrases = list.map(evidencePhrase).filter(Boolean);
  if (phrases.length) lines.push(...wrapText(`derived from: ${phrases.join('; ')}`, width));
  const gen = attrs.wasGeneratedBy;
  if (gen && typeof gen === 'object' && typeof gen.activity === 'string' && gen.activity) {
    const params = gen.parameters && typeof gen.parameters === 'object'
      ? Object.entries(gen.parameters).filter(([, v]) => v !== undefined && v !== null).map(([k, v]) => `${k}${KEEP}${value(v).replace(/\s+/g, KEEP)}`)
      : [];
    // a parameter's name and value stay on one line
    lines.push(...wrapText(`generated by: ${gen.activity}${params.length ? `, with ${params.join(', ')}` : ''}`, width).map((l) => l.split(KEEP).join(' ')));
  }
  return lines;
}

// What a card-to-tag edge says when hovered or tapped: its role ('tagged'),
// then its why and the PROV pair when the edge carries them (rosetta-tagz's
// attrs, src/corpus/buildEdges.js). An edge with none of them says only its
// role, as it did before.
function tagEdgeLabel(edge, { width = 48 } = {}) {
  const head = (edge && (edge.label || (edge.attrs && edge.attrs.label) || edge.role || edge.layer)) || '';
  const attrs = edge && edge.attrs;
  const lines = [String(head)];
  const why = attrs && typeof attrs.why === 'string' ? attrs.why : '';
  if (why) lines.push(...wrapText(why, width));
  lines.push(...provenanceLines(attrs, { width }));
  return lines.join('\n');
}

module.exports = { wrapText, evidencePhrase, provenanceLines, tagEdgeLabel };
